 "content": "def transform(grid):
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if not markers:
        return out
    r, c = markers[0]
    c -= 8
    if not (0 <= r < h and 0 <= c < 7):
        return out
    out[r][c] = 5

    # The 3x3 motifs encode successive colored strokes. The strokes are
    # traversed down the left motif column first, then down the right one.
    commands = {
        frozenset({(0, 0), (0, 1), (1, 0), (1, 2), (2, 1)}): ("R", 3),
        frozenset({(0, 0), (0, 2), (1, 0), (1, 2), (2, 0), (2, 1), (2, 2)}): ("L", 2),
        frozenset({(0, 0), (0, 2), (1, 1), (2, 1)}): ("D", 2),
        frozenset({(0, 0), (0, 1), (0, 2), (1, 1), (2, 0), (2, 2)}): ("L", 4),
        frozenset({(0, 0), (0, 1), (1, 0), (2, 1)}): ("R", 3),
    }

    for tile_col in (0, 4):
        for top in range(0, h - 2, 4):
            cells = [(i, j) for i in range(3) for j in range(3)
                     if grid[top + i][tile_col + j] != 0]
            if not cells:
                continue
            direction, length = commands[frozenset(cells)]
            color = grid[top + cells[0][0]][tile_col + cells[0][1]]
            # Each new stroke begins one row below the previous endpoint;
            # its remaining cells continue in the motif's encoded direction.
            if direction == "D":
                steps = [(1, 0)] * length
            else:
                dc = 1 if direction == "R" else -1
                steps = [(1, 0)] + [(0, dc)] * (length - 1)
            for dr, dc in steps:
                r += dr
                c += dc
                if 0 <= r < h and 0 <= c < 7:
                    out[r][c] = color
    return out
